package oracle;
import java.util.*;import java.io.*;import java.lang.reflect.*;import org.json.simple.*;import org.json.simple.parser.*;import core.game.node.item.*;import core.game.node.scenery.*;import core.game.node.entity.*;import core.game.node.entity.player.Player;import core.game.world.map.*;import core.game.world.update.*;import core.game.world.update.flag.*;import core.game.world.update.flag.chunk.*;import core.net.packet.*;
public class Support{
 static Map input;public static int tick;static Player[]players;static RegionChunk[]chunks;static List<GroundItem>grounds;static List<Scenery>objects;static List<UpdateFlag<?>>flags;static List<IoBuffer>held;static List<Object[]>sent;static List<List<GroundItem>>itemLists;static List<Object>events;static Map<String,Integer>calls;static Set<Integer>hooks;
 static int num(Object v){return((Number)v).intValue();}static Object get(Map m,String k,Object d){return m.containsKey(k)?m.get(k):d;}static Location loc(Object v){if(v==null)return null;List a=(List)v;return new Location(num(a.get(0)),num(a.get(1)),num(a.get(2)));}static Object coord(Location l){return l==null?null:Arrays.asList(l.getX(),l.getY(),l.getZ());}static Player player(Map a){Object v=get(a,"p",0);return v==null?null:players[num(v)];}static RegionChunk chunk(Map a){return chunks[num(get(a,"c",0))];}static GroundItem ground(Map a){return grounds.get(num(a.get("g")));}static int gid(GroundItem g){if(g==null)return-1;for(int i=0;i<grounds.size();i++)if(grounds.get(i)==g)return i;throw new AssertionError();}static Integer fid(UpdateFlag<?>f){if(f==null)return null;for(int i=0;i<flags.size();i++)if(flags.get(i)==f)return i;throw new AssertionError();}
 public static class Failure extends RuntimeException{}
 public static void emit(String event,Object...args){List<Object>a=new ArrayList<>();a.add(event);a.addAll(Arrays.asList(args));events.add(a);int n=calls.merge(event,1,Integer::sum);List hs=(List)get(input,"hooks",Collections.emptyList());for(int i=0;i<hs.size();i++){Map h=(Map)hs.get(i);if(event.equals(h.get("event"))&&n==num(get(h,"at",1))&&hooks.add(i))for(Object op:(List)h.get("actions"))act((Map)op);}Map f=(Map)get(input,"failures",Collections.emptyMap());if(f.containsKey(event)&&num(f.get(event))==n)throw new Failure();}
 public static void register(GroundItem g){grounds.add(g);emit("default",grounds.size()-1);}public static void send(int p,IoBuffer b){sent.add(new Object[]{p,b});emit("send",p);}public static int clipping(int z,int x,int y){int n=((x+y)&3)==0?0:1<<((x^y)&15);emit("clip",z,x,y);return n;}
 static class Foreign extends UpdateFlag<Object>{int id,value;Foreign(int i,int v){super(null);id=i;value=v;}public void write(IoBuffer b){b.put(value);}public void writeDynamic(IoBuffer b,Entity e){held.add(b);emit("foreign",id,((Player)e).id);b.put(value);}public int data(){return 0;}public int ordinal(){return 7;}}
 static void field(GroundItem g,String name,Object v){try{Field f=GroundItem.class.getDeclaredField(name);f.setAccessible(true);f.set(g,v);}catch(ReflectiveOperationException e){throw new RuntimeException(e);}}
 static Object act(Map a){String op=(String)a.get("op");switch(op){
 case"newGround":Item i=new Item(num(get(a,"id",1)),num(get(a,"amount",1)),num(get(a,"charge",1000)));String ctor=(String)get(a,"ctor","owner");Location l=loc(a.get("location"));GroundItem g;switch(ctor){case"item":g=new GroundItem(i);break;case"location":g=new GroundItem(i,l);break;case"uid":g=new GroundItem(i,l,num(get(a,"uid",7)),num(get(a,"absolute",200)));break;case"decay":g=new GroundItem(i,l,num(get(a,"decay",200)),player(a));break;default:g=new GroundItem(i,l,player(a));}return gid(g);
 case"setGround":g=ground(a);if(a.containsKey("location"))g.setLocation(loc(a.get("location")));if(a.containsKey("removed"))g.setRemoved((Boolean)a.get("removed"));if(a.containsKey("remainPrivate"))g.setRemainPrivate((Boolean)a.get("remainPrivate"));if(a.containsKey("forceVisible"))g.forceVisible=(Boolean)a.get("forceVisible");if(a.containsKey("decay"))field(g,"decayTime",num(a.get("decay")));return null;
 case"itemPrivate":return ground(a).isPrivate();case"itemActive":return ground(a).isActive();case"droppedBy":return ground(a).droppedBy(player(a));case"string":return ground(a).toString();case"setDecay":ground(a).setDecayTime(num(a.get("delay")));return null;
 case"tick":tick=num(a.get("value"));return null;
 case"player":Player p=player(a);if(a.containsKey("uid"))p.uid=num(a.get("uid"));if(a.containsKey("scene"))p.flags.anchor=loc(a.get("scene"));return null;
 case"attr":player(a).attributes.put((String)a.get("name"),(Boolean)a.get("value"));return null;
 case"base":chunk(a).currentBase=loc(a.get("location"));return null;
 case"newObject":Scenery o=new Scenery(num(get(a,"id",1)),loc(a.get("location")),num(get(a,"shape",0)),num(get(a,"rot",0)));o.renderable=(Boolean)get(a,"renderable",true);objects.add(o);return objects.size()-1;
 case"setObject":o=objects.get(num(a.get("o")));if(a.containsKey("renderable"))o.renderable=(Boolean)a.get("renderable");if(a.containsKey("location"))o.location=loc(a.get("location"));return null;
 case"place":RegionChunk c=chunk(a);("stat".equals(a.get("array"))?c.statObjects:c.objects)[num(get(a,"x",1))][num(get(a,"y",2))][num(get(a,"i",0))]=a.get("o")==null?null:objects.get(num(a.get("o")));return null;
 case"setItems":c=chunk(a);if(a.get("items")==null)c.setItems(null);else{List<GroundItem>is=new ArrayList<>();for(Object v:(List)a.get("items"))is.add(v==null?null:grounds.get(num(v)));c.setItems(is);}return null;
 case"captureItems":itemLists.add(chunk(a).getItems());return itemLists.size()-1;
 case"draw":List<Object>ids=new ArrayList<>();for(GroundItem q:chunk(a).drawItems(chunk(a).items,player(a)))ids.add(q==null?null:gid(q));return ids;
 case"newFlag":String kind=(String)a.get("kind");UpdateFlag<?>f;if(kind.equals("object"))f=new ObjectUpdateFlag(objects.get(num(a.get("o"))),(Boolean)get(a,"remove",false));else if(kind.equals("item"))f=new ItemUpdateFlag(ground(a),num(a.get("type")),num(get(a,"old",0)));else f=new Foreign(flags.size(),num(get(a,"value",88)));flags.add(f);return flags.size()-1;
 case"mutForeign":((Foreign)flags.get(num(a.get("f")))).value=num(a.get("value"));return null;
 case"flag":chunk(a).flag(a.get("f")==null?null:flags.get(num(a.get("f"))));return null;
 case"sync":chunk(a).synchronize(player(a));return null;case"update":chunk(a).update(player(a));return null;case"resetAll":ChunkUpdateTracker.INSTANCE.resetAll();return null;
 default:throw new IllegalArgumentException(op);}}
 static int dirty(){try{Field f=ChunkUpdateTracker.class.getDeclaredField("dirty");f.setAccessible(true);return((Set)f.get(null)).size();}catch(Exception e){throw new RuntimeException(e);}}
 static Object buffer(IoBuffer b){Map r=new LinkedHashMap();r.put("opcode",b.opcode);r.put("hex",b.hex());return r;}
 static Object state(){Map s=new LinkedHashMap();List<Object>gs=new ArrayList<>();for(GroundItem g:grounds){Map q=new LinkedHashMap();q.put("id",g.getId());q.put("amount",g.getAmount());q.put("charge",g.getCharge());q.put("index",g.getIndex());q.put("location",coord(g.getLocation()));q.put("dropper",g.getDropper()==null?null:g.getDropper().id);q.put("uid",g.getDropperUid());q.put("ticks",g.getTicks());q.put("decay",g.getDecayTime());q.put("removed",g.isRemoved());q.put("remainPrivate",g.isRemainPrivate());q.put("forceVisible",g.forceVisible);gs.add(q);}s.put("grounds",gs);List<Object>cs=new ArrayList<>();for(RegionChunk c:chunks){Map q=new LinkedHashMap();List<Object>fs=new ArrayList<>();for(UpdateFlag<?>f:c.rawFlags())fs.add(fid(f));q.put("flags",fs);List<Object>is=null;if(c.items!=null){is=new ArrayList<>();for(GroundItem g:c.items)is.add(g==null?null:gid(g));}q.put("items",is);q.put("base",coord(c.currentBase));cs.add(q);}s.put("chunks",cs);s.put("dirty",dirty());List<Object>ss=new ArrayList<>();for(Object[]v:sent)ss.add(Arrays.asList(v[0],buffer((IoBuffer)v[1])));s.put("sent",ss);List<Object>bs=new ArrayList<>();for(IoBuffer b:held)bs.add(buffer(b));s.put("held",bs);List<Object>ls=new ArrayList<>();for(List<GroundItem>list:itemLists){List<Object>is=new ArrayList<>();for(GroundItem g:list)is.add(g==null?null:gid(g));ls.add(is);}s.put("itemLists",ls);return s;}
 static Object evaluate(Map data){input=data;tick=num(get(data,"tick",0));players=new Player[]{new Player(0,7),new Player(1,9)};chunks=new RegionChunk[]{new RegionChunk(0,new Location(3200,3200,0)),new RegionChunk(1,new Location(3200,3200,0))};grounds=new ArrayList<>();objects=new ArrayList<>();flags=new ArrayList<>();held=new ArrayList<>();sent=new ArrayList<>();itemLists=new ArrayList<>();events=new ArrayList<>();calls=new HashMap<>();hooks=new HashSet<>();ChunkUpdateTracker.INSTANCE.resetAll();RegionChunk.dirtyListener=c->{ChunkUpdateTracker.INSTANCE.onFlagged(c);emit("dirty",c.id);};List<Object>results=new ArrayList<>();for(Object cmd:(List)data.get("actions")){Map r=new LinkedHashMap();try{r.put("value",act((Map)cmd));}catch(Throwable e){while(e.getCause()!=null)e=e.getCause();r.put("error",e instanceof Failure?"Failure":e instanceof NullPointerException?"Null":e instanceof IndexOutOfBoundsException?"Index":e.getClass().getSimpleName());}r.put("state",state());results.add(r);}Map out=new LinkedHashMap();out.put("results",results);out.put("events",events);return out;}
 public static void main(String[]args)throws Exception{BufferedReader r=new BufferedReader(new InputStreamReader(System.in,"UTF-8"));JSONParser p=new JSONParser();String line;while((line=r.readLine())!=null){Map data=(Map)p.parse(line);Map out=new LinkedHashMap(data);out.put("expected",evaluate(data));System.out.println(JSONValue.toJSONString(out));}}
}
